pattern_library.example:
// Async/await: interleaved execution
stack(
  note("c3 ~ e3 ~ g3 ~ c4 ~").s("pluck"),
  note("~ e3 ~ g3 ~ c4 ~ e4").s("pluck").early(0.25),
  note("~ ~ g3 ~ ~ c4 ~ ~").s("pluck").early(0.5)
).gain(0.7)

// Network protocol: request/response
stack(
  note("c4 e4 g4").s("square").gain(0.7),
  note("g3 e3 c3").s("sawtooth").late(0.25).gain(0.6)
).every(4, x => x.fast(1.5))

// Event loop: repeating cycles
stack(
  s("bd*4"),
  s("clap").euclid(5, 8),
  note("c3 e3 g3 c4").s("square").fast(2)
).every(4, x => x.jux(rev))

// Message queue: sequential processing
stack(
  s("industrial:3").struct("t ~ t ~ t ~ ~ t").gain(0.8),
  s("clap").late(0.125).gain(0.7),
  note("c2 ~ ~ ~ g1 ~ ~ ~").s("bass").lpf(400)
)

// Cache: hits (frequent) and misses (sparse)
stack(
  s("hh*8").gain(0.5),  // cache hits
  s("industrial:7").struct("~ ~ t ~ ~ ~ t ~").gain(0.9).speed(0.8)  // cache misses
).every(16, x => x.rev())  // cache invalidation

// Garbage collection: periodic cleanup
stack(
  note("c3 d3 e3 f3 g3 a3 b3 c4").s("pluck").fast(2),
  s("noise").struct("~ ~ ~ ~ ~ ~ ~ t").gain(0.7)  // GC sweep
).every(8, x => x.slow(4).gain(0.3))  // GC pause
